import{_ as a,o as t,c as l,O as i}from"./chunks/framework.db831a78.js";const p=JSON.parse('{"title":"多线程并发","description":"","frontmatter":{},"headers":[],"relativePath":"interview/后端/Java/03-多线程并发.md","filePath":"interview/后端/Java/03-多线程并发.md","lastUpdated":null}'),r={name:"interview/后端/Java/03-多线程并发.md"};function o(n,e,c,d,h,u){return t(),l("div",null,e[0]||(e[0]=[i('<h1 id="多线程并发" tabindex="-1">多线程并发 <a class="header-anchor" href="#多线程并发" aria-label="Permalink to &quot;多线程并发&quot;">​</a></h1><blockquote><p>常问等级：★★★ 高频必考 / ★★☆ 中频常见 / ★☆☆ 低频了解</p></blockquote><h2 id="线程有哪些状态-创建线程的几种方式-start-和-run-区别-★★★" tabindex="-1">线程有哪些状态；创建线程的几种方式；start() 和 run() 区别 ★★★ <a class="header-anchor" href="#线程有哪些状态-创建线程的几种方式-start-和-run-区别-★★★" aria-label="Permalink to &quot;线程有哪些状态；创建线程的几种方式；start() 和 run() 区别 ★★★&quot;">​</a></h2><ul><li>状态：NEW、RUNNABLE、BLOCKED、WAITING、TIMED_WAITING、TERMINATED。</li><li>创建：继承 Thread、实现 Runnable（推荐，解耦）、实现 Callable（有返回值/异常，配合 Future）、线程池。</li><li>start() 启动新线程并回调 run()；直接调 run() 只是普通方法调用，不新建线程。</li></ul><h2 id="synchronized-底层原理-锁升级过程-★★★" tabindex="-1">synchronized 底层原理；锁升级过程 ★★★ <a class="header-anchor" href="#synchronized-底层原理-锁升级过程-★★★" aria-label="Permalink to &quot;synchronized 底层原理；锁升级过程 ★★★&quot;">​</a></h2><ul><li>基于对象头 Mark Word 与 Monitor（monitorenter/monitorexit）实现。</li><li>升级：无锁 → 偏向锁（同一线程反复获得）→ 轻量级锁（竞争时 CAS 自旋）→ 重量级锁（膨胀为 Monitor，阻塞）。</li><li>JDK15 逐步废弃偏向锁。</li></ul><h2 id="volatile-作用-可见性-原子性-有序性-happens-before-★★★" tabindex="-1">volatile 作用；可见性/原子性/有序性；happens-before ★★★ <a class="header-anchor" href="#volatile-作用-可见性-原子性-有序性-happens-before-★★★" aria-label="Permalink to &quot;volatile 作用；可见性/原子性/有序性；happens-before ★★★&quot;">​</a></h2><ul><li>volatile 保证可见性（写后刷主存、读前失效工作内存，靠内存屏障）与有序性（禁止指令重排），但不保证原子性（i++ 仍非原子）。</li><li>happens-before：程序次序、监视器锁、volatile、线程 start/join、传递性等规则，是判断并发是否安全的依据。</li></ul><h2 id="aqs-原理-reentrantlock-公平-非公平锁-condition-★★★" tabindex="-1">AQS 原理；ReentrantLock 公平/非公平锁；Condition ★★★ <a class="header-anchor" href="#aqs-原理-reentrantlock-公平-非公平锁-condition-★★★" aria-label="Permalink to &quot;AQS 原理；ReentrantLock 公平/非公平锁；Condition ★★★&quot;">​</a></h2><ul><li>AQS：AbstractQueuedSynchronizer，基于 FIFO 双向队列 + volatile int state（CAS 修改）；独占（ReentrantLock）与共享（Semaphore、CountDownLatch）两种模式。</li><li>公平锁按队列顺序获取，非公平锁新线程可先 CAS 抢占（性能高、可能饥饿）；ReentrantLock 默认非公平、可重入（state 计数）。</li><li>Condition 配合 await/signal 实现精准唤醒（生产者消费者多条件）。</li></ul><h2 id="threadpoolexecutor-七大参数-四种拒绝策略-为什么不推荐-executors-★★★" tabindex="-1">ThreadPoolExecutor 七大参数；四种拒绝策略；为什么不推荐 Executors ★★★ <a class="header-anchor" href="#threadpoolexecutor-七大参数-四种拒绝策略-为什么不推荐-executors-★★★" aria-label="Permalink to &quot;ThreadPoolExecutor 七大参数；四种拒绝策略；为什么不推荐 Executors ★★★&quot;">​</a></h2><ul><li>参数：corePoolSize、maximumPoolSize、keepAliveTime、unit、workQueue、threadFactory、handler。</li><li>拒绝策略：AbortPolicy（抛异常，默认）、CallerRunsPolicy（调用者线程执行）、DiscardPolicy（丢弃）、DiscardOldestPolicy（丢最老）。</li><li>Executors 风险：Fixed/Single 队列无界（可能堆积 OOM）、Cached 线程数无上限；故建议手动 new ThreadPoolExecutor。</li></ul><h2 id="线程池参数如何根据业务设置-核心线程、空闲线程-★★★" tabindex="-1">线程池参数如何根据业务设置；核心线程、空闲线程 ★★★ <a class="header-anchor" href="#线程池参数如何根据业务设置-核心线程、空闲线程-★★★" aria-label="Permalink to &quot;线程池参数如何根据业务设置；核心线程、空闲线程 ★★★&quot;">​</a></h2><ul><li>IO 密集：线程数 = CPU 核数 * 2 起；CPU 密集：核数 + 1；需结合任务耗时、阻塞比实测。</li><li>空闲线程 keepAliveTime 超时后回收，核心线程默认不回收（allowCoreThreadTimeOut 可改为回收）；队列类型按峰值选（有界 ArrayBlockingQueue 更安全）。</li></ul><h2 id="countdownlatch-cyclicbarrier-semaphore-★★★" tabindex="-1">CountDownLatch / CyclicBarrier / Semaphore ★★★ <a class="header-anchor" href="#countdownlatch-cyclicbarrier-semaphore-★★★" aria-label="Permalink to &quot;CountDownLatch / CyclicBarrier / Semaphore ★★★&quot;">​</a></h2><ul><li>CountDownLatch：计数器减到 0 释放等待线程，一次性，用于主线程等待子任务完成。</li><li>CyclicBarrier：栅栏，N 个线程相互等待到齐后继续，可重复使用，用于多线程某一阶段同步。</li><li>Semaphore：信号量，控制并发访问数（限流、资源池）。</li></ul><h2 id="concurrenthashmap、copyonwritearraylist-原理-★★★" tabindex="-1">ConcurrentHashMap、CopyOnWriteArrayList 原理 ★★★ <a class="header-anchor" href="#concurrenthashmap、copyonwritearraylist-原理-★★★" aria-label="Permalink to &quot;ConcurrentHashMap、CopyOnWriteArrayList 原理 ★★★&quot;">​</a></h2><ul><li>ConcurrentHashMap：见 Java 基础篇（1.8 synchronized + CAS 桶级锁 + 红黑树）。</li><li>CopyOnWriteArrayList：写时复制，写操作复制整个数组再改（add 用 ReentrantLock），读无锁；适合读多写极少，写开销大、内存占用高。</li></ul><h2 id="死锁四个条件-如何避免-活锁、饥饿-★★★" tabindex="-1">死锁四个条件；如何避免；活锁、饥饿 ★★★ <a class="header-anchor" href="#死锁四个条件-如何避免-活锁、饥饿-★★★" aria-label="Permalink to &quot;死锁四个条件；如何避免；活锁、饥饿 ★★★&quot;">​</a></h2><ul><li>条件：互斥、持有并等待、不可剥夺、循环等待。破坏任一即可，常用破坏「循环等待」：按固定顺序加锁。</li><li>定位：jstack 看线程 dump 中的 Found one Java-level deadlock。</li><li>活锁：线程互相礼让导致停滞；饥饿：低优先级/不公平锁导致永远拿不到资源。</li></ul><h2 id="线程安全问题产生原因-★★☆" tabindex="-1">线程安全问题产生原因 ★★☆ <a class="header-anchor" href="#线程安全问题产生原因-★★☆" aria-label="Permalink to &quot;线程安全问题产生原因 ★★☆&quot;">​</a></h2><ul><li>多线程共享可变数据，读写交叠导致数据竞争；根本原因是可见性、原子性、有序性被破坏，通过 volatile、synchronized、原子类、并发容器、不可变对象解决。</li></ul><h2 id="threadlocal-原理与内存泄漏-★★★" tabindex="-1">ThreadLocal 原理与内存泄漏 ★★★ <a class="header-anchor" href="#threadlocal-原理与内存泄漏-★★★" aria-label="Permalink to &quot;ThreadLocal 原理与内存泄漏 ★★★&quot;">​</a></h2><ul><li>每个线程持有 ThreadLocalMap，key 是 ThreadLocal 的弱引用，value 是值；线程不销毁则 entry 不回收。</li><li>内存泄漏：ThreadLocal 被 GC 后 key 变 null，value 仍被 Entry 强引用；用完调用 remove()。Entry 的 key 用弱引用正是在 ThreadLocal 回收后允许下次 get/set 清理。</li></ul><h2 id="cas-原理与-aba-问题-★★★" tabindex="-1">CAS 原理与 ABA 问题 ★★★ <a class="header-anchor" href="#cas-原理与-aba-问题-★★★" aria-label="Permalink to &quot;CAS 原理与 ABA 问题 ★★★&quot;">​</a></h2><ul><li>CAS：Compare And Swap，比较内存值与预期，相等则交换，底层 CPU 原子指令（cmpxchg）；缺点是 ABA（值被改为 A 又改回 A）。</li><li>ABA 解决：AtomicStampedReference / AtomicMarkableReference 加版本号。</li></ul><h2 id="原子类-atomicinteger、longadder-★★☆" tabindex="-1">原子类 AtomicInteger、LongAdder ★★☆ <a class="header-anchor" href="#原子类-atomicinteger、longadder-★★☆" aria-label="Permalink to &quot;原子类 AtomicInteger、LongAdder ★★☆&quot;">​</a></h2><ul><li>AtomicInteger 基于 volatile + CAS（Unsafe）；LongAdder 采用分段累加（Cell 分散热点），高并发累加性能更好，sum 结果非实时精确。</li></ul><h2 id="completablefuture-异步编排-★★★" tabindex="-1">CompletableFuture 异步编排 ★★★ <a class="header-anchor" href="#completablefuture-异步编排-★★★" aria-label="Permalink to &quot;CompletableFuture 异步编排 ★★★&quot;">​</a></h2><ul><li>用于异步任务编排：thenApply（有依赖）、thenAccept/run、thenCombine（合并两个）、allOf/anyOf（多任务汇总/任一）、exceptionally（异常处理），比 Future 回调更灵活。</li></ul><h2 id="jmm-内存屏障、指令重排-★★☆" tabindex="-1">JMM 内存屏障、指令重排 ★★☆ <a class="header-anchor" href="#jmm-内存屏障、指令重排-★★☆" aria-label="Permalink to &quot;JMM 内存屏障、指令重排 ★★☆&quot;">​</a></h2><ul><li>内存屏障：屏障前写对屏障后读可见；volatile 写插 StoreStore+StoreLoad，读插 LoadLoad+LoadStore。</li><li>指令重排：编译器与 CPU 为提高性能重排指令，在无同步时可能改变语义；双重校验锁单例需 volatile 防止重排。</li></ul><h2 id="blockingqueue、线程中断-interrupt-★★☆" tabindex="-1">BlockingQueue、线程中断 interrupt ★★☆ <a class="header-anchor" href="#blockingqueue、线程中断-interrupt-★★☆" aria-label="Permalink to &quot;BlockingQueue、线程中断 interrupt ★★☆&quot;">​</a></h2><ul><li>BlockingQueue：put/take 阻塞式（ArrayBlockingQueue、LinkedBlockingQueue、SynchronousQueue、DelayQueue），是线程池与生产者消费者的基础。</li><li>interrupt()：设置中断标志，不真正停止线程；sleep/wait 抛 InterruptedException 并清除标志；配合 isInterrupted() 优雅退出。</li></ul><h2 id="synchronized-与-reentrantlock-区别-前端转全栈必考-★★★" tabindex="-1">synchronized 与 ReentrantLock 区别（前端转全栈必考）★★★ <a class="header-anchor" href="#synchronized-与-reentrantlock-区别-前端转全栈必考-★★★" aria-label="Permalink to &quot;synchronized 与 ReentrantLock 区别（前端转全栈必考）★★★&quot;">​</a></h2><table><thead><tr><th>区别</th><th>synchronized</th><th>ReentrantLock</th></tr></thead><tbody><tr><td>实现</td><td>JVM 层面（Monitor 指令）</td><td>JDK 层面（AQS + CAS）</td></tr><tr><td>释放</td><td>自动释放（代码块结束/异常）</td><td>需手动 unlock（finally 中）</td></tr><tr><td>功能</td><td>不可中断、无超时、非公平</td><td>可中断 lockInterruptibly、超时 tryLock、可选公平、多条件 Condition</td></tr><tr><td>底层</td><td>锁升级（偏向/轻量/重量）</td><td>基于 AQS 队列</td></tr></tbody></table><ul><li>建议：简单同步场景用 synchronized（简洁、自动释放）；需要可中断/超时/多条件/公平锁时用 ReentrantLock。JDK1.6 优化后二者性能差距很小。</li></ul><h2 id="sleep-与-wait-区别-★★★" tabindex="-1">sleep() 与 wait() 区别 ★★★ <a class="header-anchor" href="#sleep-与-wait-区别-★★★" aria-label="Permalink to &quot;sleep() 与 wait() 区别 ★★★&quot;">​</a></h2><ul><li>来源：sleep 是 Thread 的静态方法；wait 是 Object 的实例方法。</li><li>锁：sleep 不释放锁；wait 释放锁（必须在 synchronized 块内调用，否则抛 IllegalMonitorStateException）。</li><li>唤醒：sleep 到时间自动醒来；wait 需要 notify/notifyAll 唤醒，或带超时参数。</li><li>用途：sleep 只是让线程休眠、让出 CPU；wait 用于线程间协作（如生产者-消费者等待条件满足）。</li></ul><h2 id="volatile-与-synchronized-区别-★★☆" tabindex="-1">volatile 与 synchronized 区别 ★★☆ <a class="header-anchor" href="#volatile-与-synchronized-区别-★★☆" aria-label="Permalink to &quot;volatile 与 synchronized 区别 ★★☆&quot;">​</a></h2><ul><li>volatile 只保证可见性和有序性，不保证原子性，只能修饰变量，是轻量级同步。</li><li>synchronized 保证可见性 + 原子性 + 有序性，可修饰方法/代码块，会加锁阻塞。</li><li>选择：仅需状态标志可见用 volatile；涉及复合操作（读改写）用 synchronized 或原子类。</li></ul><h2 id="wait-notify-线程协作机制-★★☆" tabindex="-1">wait/notify 线程协作机制 ★★☆ <a class="header-anchor" href="#wait-notify-线程协作机制-★★☆" aria-label="Permalink to &quot;wait/notify 线程协作机制 ★★☆&quot;">​</a></h2><ul><li>wait()：释放锁并进入等待，直到被 notify/notifyAll 唤醒；notify 唤醒一个等待线程，notifyAll 唤醒所有。</li><li>必须在 synchronized 内调用（持有对象监视器）；等待条件判断要用 <code>while</code> 而非 <code>if</code>，防止虚假唤醒导致条件不满足仍往下执行。</li><li>与 Condition 对比：Condition 可对同一锁创建多个条件队列，实现更精细的等待/唤醒。</li></ul>',43)]))}const b=a(r,[["render",o]]);export{p as __pageData,b as default};
